create extension if not exists pgcrypto;
create extension if not exists btree_gist;
create type app_role as enum ('superadmin','admin','user');
create type jenis_proker as enum ('rutin','visioner','aksidental');
create type status_proker as enum ('menunggu','ditinjau','disetujui','ditolak','direvisi');
create table lembaga(id uuid primary key default gen_random_uuid(), nama text not null unique, urutan int not null default 0);
create table bidang(id uuid primary key default gen_random_uuid(), lembaga_id uuid not null references lembaga on delete restrict, nama text not null, urutan int not null default 0, unique(lembaga_id,nama));
create table tim_kerja(id uuid primary key default gen_random_uuid(), bidang_id uuid not null references bidang on delete restrict, nama text not null, urutan int not null default 0, unique(bidang_id,nama));
create table profiles(id uuid primary key references auth.users on delete cascade, username text not null unique check(username ~ '^[a-z0-9._-]+$'), role app_role not null default 'user', tim_kerja_id uuid not null unique references tim_kerja on delete cascade, nama_koordinator text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create unique index only_one_superadmin on profiles(role) where role='superadmin';
create table periode_input(id uuid primary key default gen_random_uuid(), tahun_program int not null unique check(tahun_program between 2000 and 2100), tanggal_mulai date not null, tanggal_selesai date not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check(tanggal_selesai >= tanggal_mulai), exclude using gist(daterange(tanggal_mulai,tanggal_selesai,'[]') with &&));
create table visi_misi(id uuid primary key default gen_random_uuid(), singleton boolean not null default true unique check(singleton), visi text not null, updated_at timestamptz not null default now());
create table misi(id uuid primary key default gen_random_uuid(), nomor int not null unique, teks text not null, outcome text not null);
create table milestone(id uuid primary key default gen_random_uuid(), misi_id uuid not null references misi on delete cascade, nomor int not null, teks text not null, unique(misi_id,nomor));
create table proker(id uuid primary key default gen_random_uuid(), tim_kerja_id uuid not null references tim_kerja on delete cascade, created_by uuid references profiles on delete set null, tahun_program int not null, jenis jenis_proker not null, status status_proker not null default 'menunggu', misi_id uuid references misi on delete set null, milestone_id uuid references milestone on delete set null, visi_teks text, misi_teks text, outcome_teks text, milestone_teks text, sasaran_program text not null, indikator_keberhasilan text not null, target text not null, nama_kegiatan text not null, rentang_waktu boolean not null default false, tanggal_mulai date not null, tanggal_selesai date not null, penanggung_jawab text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check((jenis='visioner')=(visi_teks is not null and misi_teks is not null and outcome_teks is not null and milestone_teks is not null)), check((rentang_waktu and tanggal_selesai>=tanggal_mulai) or (not rentang_waktu and tanggal_selesai=tanggal_mulai)), check(jenis<>'aksidental' or status<>'menunggu'));
create index on proker(tim_kerja_id); create index on proker(tahun_program,status);
create table proker_anggaran(id uuid primary key default gen_random_uuid(), proker_id uuid not null references proker on delete cascade, urutan int not null default 0, nama text not null, jumlah_item integer not null check(jumlah_item>0), nominal numeric(15,2) not null check(nominal>=0));
create table evaluasi(id uuid primary key default gen_random_uuid(), proker_id uuid not null unique references proker on delete cascade, created_by uuid references profiles on delete set null, hasil_kegiatan text not null, capaian_persen smallint not null check(capaian_persen between 0 and 100), rentang_waktu boolean not null, tanggal_mulai date not null, tanggal_selesai date not null, keterangan_tambahan text, created_at timestamptz not null default now(), check((rentang_waktu and tanggal_selesai>=tanggal_mulai) or (not rentang_waktu and tanggal_selesai=tanggal_mulai)));
create table evaluasi_anggaran(id uuid primary key default gen_random_uuid(), evaluasi_id uuid not null references evaluasi on delete cascade, urutan int not null default 0, nama text not null, jumlah_item integer not null check(jumlah_item>0), nominal numeric(15,2) not null check(nominal>=0));
create table evaluasi_file(id uuid primary key default gen_random_uuid(), evaluasi_id uuid not null references evaluasi on delete cascade, storage_path text not null unique, nama_file text not null, mime_type text not null check(mime_type in ('image/jpeg','image/png','application/pdf')), ukuran_bytes bigint not null check(ukuran_bytes>0 and ukuran_bytes<=10485760), created_at timestamptz not null default now());
create function hari_ini() returns date language sql stable as $$ select (now() at time zone 'Asia/Jakarta')::date $$;
create function current_app_role() returns app_role language sql stable security definer set search_path=public as $$ select role from profiles where id=auth.uid() $$;
create function current_tim_kerja_id() returns uuid language sql stable security definer set search_path=public as $$ select tim_kerja_id from profiles where id=auth.uid() $$;
create function periode_aktif() returns setof periode_input language sql stable security definer set search_path=public as $$ select * from periode_input where hari_ini() between tanggal_mulai and tanggal_selesai $$;
create function proker_status_efektif(p_id uuid) returns status_proker language sql stable security definer set search_path=public as $$ select case when p.status='menunggu' and pi.tanggal_selesai<hari_ini() then 'ditinjau'::status_proker else p.status end from proker p left join periode_input pi on pi.tahun_program=p.tahun_program where p.id=p_id $$;
create view proker_v with(security_invoker=true) as select p.*, case when p.status='menunggu' and pi.tanggal_selesai<hari_ini() then 'ditinjau'::status_proker else p.status end status_efektif from proker p left join periode_input pi on pi.tahun_program=p.tahun_program;
create function touch_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end $$;
do $$ declare t text; begin foreach t in array array['profiles','periode_input','visi_misi','proker'] loop execute format('create trigger %I_updated before update on %I for each row execute function touch_updated_at()',t,t); end loop; end $$;
create function check_evaluasi_insert() returns trigger language plpgsql security definer set search_path=public as $$ begin if not exists(select 1 from proker where id=new.proker_id and status='disetujui') then raise exception 'Evaluasi hanya untuk proker disetujui'; end if; return new; end $$;
create trigger evaluasi_approved before insert on evaluasi for each row execute function check_evaluasi_insert();
create function limit_evaluasi_files() returns trigger language plpgsql as $$ begin if (select count(*) from evaluasi_file where evaluasi_id=new.evaluasi_id)>=10 then raise exception 'Maksimal 10 file'; end if; return new; end $$;
create trigger evaluasi_file_limit before insert on evaluasi_file for each row execute function limit_evaluasi_files();
create function set_proker_status(p_id uuid,p_status status_proker) returns void language plpgsql security definer set search_path=public as $$ begin if current_app_role() not in ('admin','superadmin') or proker_status_efektif(p_id) not in ('ditinjau','ditolak','direvisi') or p_status not in ('ditinjau','disetujui','ditolak','direvisi') then raise exception 'Tidak diizinkan'; end if; perform set_config('app.status_rpc_id',p_id::text,true); update proker set status=p_status where id=p_id; end $$;
create function guard_proker_update() returns trigger language plpgsql security definer set search_path=public as $$ begin
 if current_setting('app.status_rpc_id',true)=old.id::text and current_app_role() in ('admin','superadmin') then return new; end if;
 if current_app_role() in ('admin','superadmin') and old.tim_kerja_id=current_tim_kerja_id() and proker_status_efektif(old.id)='menunggu' then
   if new.status<>old.status or new.tim_kerja_id<>old.tim_kerja_id or new.tahun_program<>old.tahun_program or new.jenis<>old.jenis then raise exception 'Perubahan proker tidak diizinkan'; end if;
 elsif current_app_role() in ('admin','superadmin') then
   if proker_status_efektif(old.id) not in ('ditinjau','ditolak','direvisi') or new.tim_kerja_id<>old.tim_kerja_id or new.tahun_program<>old.tahun_program or new.jenis<>old.jenis then raise exception 'Perubahan proker tidak diizinkan'; end if;
   if new.status<>old.status and new.status<>'direvisi' then raise exception 'Perubahan status harus melalui fungsi set_proker_status'; end if;
   if new.status='direvisi' and new.status is distinct from old.status and (to_jsonb(new)-'status'-'updated_at')=(to_jsonb(old)-'status'-'updated_at') then raise exception 'Perubahan status harus melalui fungsi set_proker_status'; end if;
   if new.status<>'direvisi' then raise exception 'Proker yang diedit harus berstatus direvisi'; end if;
 elsif old.tim_kerja_id<>current_tim_kerja_id() or proker_status_efektif(old.id)<>'menunggu' or new.status<>old.status or new.tahun_program<>old.tahun_program or new.jenis<>old.jenis or new.tim_kerja_id<>old.tim_kerja_id then raise exception 'Perubahan proker tidak diizinkan';
 end if; return new; end $$;
create trigger proker_update_guard before update on proker for each row execute function guard_proker_update();
alter table lembaga enable row level security; alter table bidang enable row level security; alter table tim_kerja enable row level security; alter table profiles enable row level security; alter table periode_input enable row level security; alter table visi_misi enable row level security; alter table misi enable row level security; alter table milestone enable row level security; alter table proker enable row level security; alter table proker_anggaran enable row level security; alter table evaluasi enable row level security; alter table evaluasi_anggaran enable row level security; alter table evaluasi_file enable row level security;
create policy org_read on lembaga for select to authenticated using(true); create policy bidang_read on bidang for select to authenticated using(true); create policy team_read on tim_kerja for select to authenticated using(true);
create policy team_insert on tim_kerja for insert to authenticated with check(current_app_role()='superadmin'); create policy team_update on tim_kerja for update to authenticated using(current_app_role()='superadmin') with check(current_app_role()='superadmin');
create policy profiles_read on profiles for select to authenticated using(id=auth.uid() or current_app_role() in ('admin','superadmin'));
create policy period_read on periode_input for select to authenticated using(true); create policy period_insert on periode_input for insert to authenticated with check(current_app_role() in ('admin','superadmin')); create policy period_update on periode_input for update to authenticated using(current_app_role() in ('admin','superadmin')) with check(current_app_role() in ('admin','superadmin'));
create policy strategy_read on visi_misi for select to authenticated using(true); create policy strategy_admin on visi_misi for all to authenticated using(current_app_role()='superadmin') with check(current_app_role()='superadmin');
create policy misi_read on misi for select to authenticated using(true); create policy misi_admin on misi for all to authenticated using(current_app_role()='superadmin') with check(current_app_role()='superadmin'); create policy milestone_read on milestone for select to authenticated using(true); create policy milestone_admin on milestone for all to authenticated using(current_app_role()='superadmin') with check(current_app_role()='superadmin');
create policy proker_read on proker for select to authenticated using(current_app_role() in ('admin','superadmin') or tim_kerja_id=current_tim_kerja_id());
create policy proker_insert on proker for insert to authenticated with check(tim_kerja_id=current_tim_kerja_id() and created_by=auth.uid() and ((jenis in ('rutin','visioner') and exists(select 1 from periode_aktif() pi where pi.tahun_program=proker.tahun_program) and status='menunggu') or (jenis='aksidental' and not exists(select 1 from periode_aktif()) and tahun_program=extract(year from hari_ini())::int and status='ditinjau')));
create policy proker_owner_update on proker for update to authenticated using(tim_kerja_id=current_tim_kerja_id() and proker_status_efektif(id)='menunggu') with check(tim_kerja_id=current_tim_kerja_id() and proker_status_efektif(id)='menunggu');
create policy proker_admin_update on proker for update to authenticated using(current_app_role() in ('admin','superadmin') and proker_status_efektif(id) in ('ditinjau','ditolak','direvisi')) with check(current_app_role() in ('admin','superadmin') and status='direvisi');
create policy proker_owner_delete on proker for delete to authenticated using(tim_kerja_id=current_tim_kerja_id() and proker_status_efektif(id)='menunggu');
create policy proker_cost_read on proker_anggaran for select to authenticated using(exists(select 1 from proker p where p.id=proker_id and (current_app_role() in ('admin','superadmin') or p.tim_kerja_id=current_tim_kerja_id())));
create policy proker_cost_insert on proker_anggaran for insert to authenticated with check(exists(select 1 from proker p where p.id=proker_id and ((p.tim_kerja_id=current_tim_kerja_id() and proker_status_efektif(p.id)='menunggu') or (current_app_role() in ('admin','superadmin') and proker_status_efektif(p.id) in ('ditinjau','ditolak','direvisi')))));
create policy proker_cost_update on proker_anggaran for update to authenticated using(exists(select 1 from proker p where p.id=proker_id and ((p.tim_kerja_id=current_tim_kerja_id() and proker_status_efektif(p.id)='menunggu') or (current_app_role() in ('admin','superadmin') and proker_status_efektif(p.id) in ('ditinjau','ditolak','direvisi'))))) with check(exists(select 1 from proker p where p.id=proker_id and ((p.tim_kerja_id=current_tim_kerja_id() and proker_status_efektif(p.id)='menunggu') or (current_app_role() in ('admin','superadmin') and proker_status_efektif(p.id) in ('ditinjau','ditolak','direvisi')))));
create policy proker_cost_delete on proker_anggaran for delete to authenticated using(exists(select 1 from proker p where p.id=proker_id and ((p.tim_kerja_id=current_tim_kerja_id() and proker_status_efektif(p.id)='menunggu') or (current_app_role() in ('admin','superadmin') and proker_status_efektif(p.id) in ('ditinjau','ditolak','direvisi')))));
create policy eval_read on evaluasi for select to authenticated using(current_app_role() in ('admin','superadmin') or exists(select 1 from proker p where p.id=proker_id and p.tim_kerja_id=current_tim_kerja_id()));
create policy eval_insert on evaluasi for insert to authenticated with check(created_by=auth.uid() and exists(select 1 from proker p where p.id=proker_id and p.tim_kerja_id=current_tim_kerja_id() and p.status='disetujui'));
create policy eval_cost_insert on evaluasi_anggaran for insert to authenticated with check(exists(select 1 from evaluasi e join proker p on p.id=e.proker_id where e.id=evaluasi_id and p.tim_kerja_id=current_tim_kerja_id() and p.status='disetujui'));
create policy eval_file_insert on evaluasi_file for insert to authenticated with check(exists(select 1 from evaluasi e join proker p on p.id=e.proker_id where e.id=evaluasi_id and p.tim_kerja_id=current_tim_kerja_id() and p.status='disetujui'));
create policy eval_cost_read on evaluasi_anggaran for select to authenticated using(exists(select 1 from evaluasi e join proker p on p.id=e.proker_id where e.id=evaluasi_id and (current_app_role() in ('admin','superadmin') or p.tim_kerja_id=current_tim_kerja_id())));
create policy eval_file_read on evaluasi_file for select to authenticated using(exists(select 1 from evaluasi e join proker p on p.id=e.proker_id where e.id=evaluasi_id and (current_app_role() in ('admin','superadmin') or p.tim_kerja_id=current_tim_kerja_id())));
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('bukti-evaluasi','bukti-evaluasi',false,10485760,array['image/jpeg','image/png','application/pdf']) on conflict(id) do nothing;
